#!/usr/bin/env python3
"""FS3 v201 - NTF ships in 3D, turrets that turn, one loading bar.

    NTF        Aeolus, Deimos, Fenris, Leviathan, Orion and Hecate of the
               NTF in 3D, with their own models and maps from the NTF
               texture mod, armed with their models' turrets like the
               GTVA ships (v199).
    Turrets    Turret bases turn to their target and the barrels tip over
               towards it, as in FreeSpace (at rest the barrels point along
               the turret's normal). Radar dishes and the Mjolnir's rings
               spin at their FreeSpace rate. Only the picture moves.
    Hits       A 3D ship is hit wherever her model is, also beyond the
               sprite's box (the Sathanas' claws).
    Shots      Silvio's layer order: shots are drawn over the ships now.
               What a turret on the far flank fires comes out from behind
               the hull, like the beams since v198.
    Loading    One bar: the loading page fetches the game and the models
               (packed, about 53 MB more on the first visit); the game
               carries the same bar on while it puts the models on the
               graphics card, then the title shows. No bar on the title.

Needs v200. Edits src/20_render.js, 40_world.js, 50_combat.js,
57_turrets.js, 58_model3d.js, 59_field3d.js, 70_ui.js, fieldsim.js,
build_game.py and loader.html. New model files: models_v201.zip. Run
assemble.py 201 afterwards.
"""
import base64
import os
import sys

if not os.path.exists("src/59_field3d.js"):
    sys.exit("Abbruch: erst v200 einspielen.")
_f = open("src/59_field3d.js", encoding="utf-8").read()
if "F3D_PRE" not in _f:
    sys.exit("Abbruch: erst v200 einspielen.")
if "f3dNodeMats" in _f:
    sys.exit("Abbruch: v201 ist schon eingespielt.")
for _p in ("build_game.py", "loader.html"):
    if not os.path.exists(_p):
        sys.exit("Abbruch: %s fehlt in diesem Ordner." % _p)

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
